# area: abstract_classes
# hypothesis: A TypeIs[Source] guard called from a nested closure inside a method still narrows its argument to Source, while a static checker still rejects passing the runtime-registered Fixed where Source is required.
from abc import ABC, abstractmethod
from typing import TypeIs, reveal_type


class Source(ABC):
    @property
    @abstractmethod
    def name(self) -> str:
        ...


class AttrSource(Source):
    name = 'attr'


class Fixed:
    @property
    def name(self) -> str:
        return 'fixed'


Source.register(Fixed)


class Checks:
    @staticmethod
    def is_source(x: object) -> TypeIs[Source]:
        return isinstance(x, Source)

    def describe(self, x: AttrSource | Fixed) -> str:
        def inner() -> str:
            if Checks.is_source(x):
                reveal_type(x)
                return x.name
            return 'none'
        return inner()


def need_source(s: Source) -> str:
    return s.name


def bad(f: Fixed) -> str:
    return need_source(f)  # expect-error: Fixed is not statically a Source


print(Checks().describe(AttrSource()))
print(Checks().describe(Fixed()))
print(bad(Fixed()))
print(issubclass(Fixed, Source))
